#requires -Modules Pester

<#
  Workflow / pipeline test harness.

  This file is the REQUIRED end-to-end harness: every functional test case is
  exercised by actually running the GitHub Actions workflow through `act`
  (nektos/act) inside a Docker container — the script is never invoked directly
  here. For each case we:

    1. Build a throwaway git repo containing the project files plus that case's
       fixture data (and an env-tuned copy of the workflow).
    2. Run `act push --rm`, capturing all output.
    3. Append the output to act-result.txt (the required artifact), delimited.
    4. Assert act exited 0, that every job reports "Job succeeded", and that the
       output contains the EXACT expected values for that case's input.

  A separate Describe block validates the workflow's static structure
  (triggers / jobs / steps / script references) and that actionlint passes.

  NOTE: act runs are expensive (~30-90s each). There are exactly three act
  integration cases by design.
#>

BeforeAll {
    $script:Root          = $PSScriptRoot
    $script:WorkflowPath  = Join-Path $Root '.github/workflows/secret-rotation-validator.yml'
    $script:WorkflowText  = Get-Content -LiteralPath $script:WorkflowPath -Raw
    $script:ActResultFile = Join-Path $Root 'act-result.txt'

    # Start the artifact fresh for this run.
    Set-Content -LiteralPath $script:ActResultFile -Value "# act integration results`n" -Encoding utf8

    # Files the workflow needs in any temp repo.
    $script:ProjectFiles = @(
        'SecretRotation.psm1',
        'Invoke-RotationValidator.ps1',
        'SecretRotation.Tests.ps1',
        '.actrc'
    )

    # Build a temp git repo for a case, run act, capture output, append to the
    # shared artifact, and return @{ ExitCode; Output }.
    function Invoke-ActCase {
        param(
            [Parameter(Mandatory)][string]$Name,
            [Parameter(Mandatory)][string]$FixtureJson,
            [string]$WarningDays = '14',
            [string]$OutputFormat = 'markdown',
            [string]$ReferenceDate = '2026-06-26'
        )

        $tmp = Join-Path ([System.IO.Path]::GetTempPath()) ("act-" + [guid]::NewGuid())
        New-Item -ItemType Directory -Path $tmp -Force | Out-Null
        try {
            # Copy project files.
            foreach ($f in $script:ProjectFiles) {
                Copy-Item -LiteralPath (Join-Path $script:Root $f) -Destination (Join-Path $tmp $f) -Force
            }

            # Fixture data for this case.
            $fixDir = Join-Path $tmp 'fixtures'
            New-Item -ItemType Directory -Path $fixDir -Force | Out-Null
            Set-Content -LiteralPath (Join-Path $fixDir 'secrets.json') -Value $FixtureJson -Encoding utf8

            # Workflow, with env defaults tuned for this case. Editing the env
            # block (rather than passing act --env) guarantees the values win,
            # since workflow-level env overrides container env in GitHub/act.
            $wfDir = Join-Path $tmp '.github/workflows'
            New-Item -ItemType Directory -Path $wfDir -Force | Out-Null
            $wf = $script:WorkflowText
            $wf = $wf -replace "WARNING_DAYS: '[^']*'", "WARNING_DAYS: '$WarningDays'"
            $wf = $wf -replace "OUTPUT_FORMAT: \w+",       "OUTPUT_FORMAT: $OutputFormat"
            $wf = $wf -replace "REFERENCE_DATE: '[^']*'",  "REFERENCE_DATE: '$ReferenceDate'"
            Set-Content -LiteralPath (Join-Path $wfDir 'secret-rotation-validator.yml') -Value $wf -Encoding utf8

            # Make it a git repo (checkout step + act both expect one).
            Push-Location $tmp
            try {
                git init -q 2>&1 | Out-Null
                git config user.email 'harness@example.com' 2>&1 | Out-Null
                git config user.name  'harness'             2>&1 | Out-Null
                git add -A 2>&1 | Out-Null
                git commit -q -m 'test case' 2>&1 | Out-Null

                $out = & act push --rm -W .github/workflows/secret-rotation-validator.yml 2>&1
                $code = $LASTEXITCODE
            } finally {
                Pop-Location
            }

            $text = ($out | Out-String)

            # Append to the required artifact, clearly delimited.
            $delim = "`n========== CASE: $Name (warningDays=$WarningDays format=$OutputFormat) ==========`n"
            Add-Content -LiteralPath $script:ActResultFile -Value $delim -Encoding utf8
            Add-Content -LiteralPath $script:ActResultFile -Value $text  -Encoding utf8
            Add-Content -LiteralPath $script:ActResultFile -Value "`n[act exit code: $code]`n" -Encoding utf8

            return @{ ExitCode = $code; Output = $text }
        } finally {
            Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue
        }
    }
}

Describe 'Workflow static structure' {

    It 'is valid according to actionlint' {
        $null = & actionlint $script:WorkflowPath 2>&1
        $LASTEXITCODE | Should -Be 0
    }

    It 'declares all required trigger events' {
        $script:WorkflowText | Should -Match '(?m)^on:'
        $script:WorkflowText | Should -Match '(?m)^\s+push:'
        $script:WorkflowText | Should -Match '(?m)^\s+pull_request:'
